public class FastDateFormat_format_TriageGen1Test {

    @Test
    public void testFormatWithTimeZoneForcedTrue() {
        // Arrange
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone forcedTZ = TimeZone.getTimeZone("UTC");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, forcedTZ);

        // Use reflection or assume the internal state via getInstance(pattern, timeZone)
        // In FastDateFormat, getInstance(pattern, timeZone) sets mTimeZoneForced to true

        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("GMT+8"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        // 2023-10-27 10:00:00 GMT+8 is 2023-10-27 02:00:00 UTC
        String expected = "2023-10-27 02:00:00";
        assertEquals(expected, result.toString());

        // Verify original calendar was not mutated (cloned)
        assertEquals(10, calendar.get(Calendar.HOUR));
    }

    @Test
    public void testFormatWithTimeZoneForcedFalse() {
        // Arrange
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone tz = TimeZone.getTimeZone("GMT+8");
        // To ensure mTimeZoneForced is false, we use a pattern without a specific TimeZone 
        // or use the default getInstance which uses system default.
        // However, based on FastDateFormat implementation, getInstance(pattern) 
        // results in mTimeZoneForced = false.
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance(tz);
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        // Since mTimeZoneForced is false, it uses the calendar's own timezone
        String expected = "2023-10-27 10:00:00";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testFormatWithEmptyBuffer() {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        calendar.set(2025, Calendar.JANUARY, 1);
        StringBuffer buf = new StringBuffer();

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        assertEquals("2025", result.toString());
    }

    @Test
    public void testFormatAppendsToExistingBuffer() {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        calendar.set(2025, Calendar.JANUARY, 1);
        StringBuffer buf = new StringBuffer("Start-");

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        assertEquals("Start-2025", result.toString());
    }
}
